import { Space, Tag, Tooltip, Typography } from 'antd';
import {
  AlignLeftOutlined,
  ApartmentOutlined,
  AppstoreOutlined,
  ArrowDownOutlined,
  ArrowUpOutlined,
  BranchesOutlined,
  CalendarOutlined,
  CheckCircleOutlined,
  CheckSquareOutlined,
  ColumnWidthOutlined,
  DeleteOutlined,
  DownSquareOutlined,
  EditOutlined,
  EnvironmentOutlined,
  EyeInvisibleOutlined,
  FontSizeOutlined,
  FormOutlined,
  HolderOutlined,
  LockOutlined,
  NumberOutlined,
  ShopOutlined,
  SwapOutlined,
  WarningOutlined
} from '@ant-design/icons';
import { useIntl } from '@kne/react-intl';
import { getFieldDefinition, resolveFieldTypeLabel } from './fieldRegistry';
import RowActions, { orderActions } from './RowActions';
import style from './style.module.scss';
import { resolveLocaleText } from './localeText';
import { useLocaleTextLanguages } from './LocaleTextInput';
import { formatVisibleWhen, hasInvalidCondition, hasVisibleWhen } from './fieldCondition';

const { Text } = Typography;

const TYPE_TAG_COLORS = {
  Input: 'blue',
  TextArea: 'blue',
  InputNumber: 'cyan',
  Select: 'geekblue',
  RadioGroup: 'purple',
  CheckboxGroup: 'purple',
  RadioGroupOther: 'purple',
  CheckboxGroupOther: 'purple',
  SuperSelectList: 'gold',
  SuperSelectTableList: 'gold',
  SuperSelectTree: 'gold',
  SuperSelectCascader: 'gold',
  SelectFunction: 'orange',
  SelectIndustry: 'orange',
  SelectAddress: 'orange',
  Switch: 'green',
  Checkbox: 'green',
  DatePicker: 'lime'
};

const TYPE_TAG_ICONS = {
  Input: FontSizeOutlined,
  TextArea: AlignLeftOutlined,
  InputNumber: NumberOutlined,
  Select: DownSquareOutlined,
  RadioGroup: CheckCircleOutlined,
  CheckboxGroup: CheckSquareOutlined,
  RadioGroupOther: CheckCircleOutlined,
  CheckboxGroupOther: CheckSquareOutlined,
  SuperSelectList: AppstoreOutlined,
  SuperSelectTableList: AppstoreOutlined,
  SuperSelectTree: AppstoreOutlined,
  SuperSelectCascader: AppstoreOutlined,
  SelectFunction: ApartmentOutlined,
  SelectIndustry: ShopOutlined,
  SelectAddress: EnvironmentOutlined,
  Switch: SwapOutlined,
  Checkbox: CheckSquareOutlined,
  DatePicker: CalendarOutlined
};

export const getFieldTypeIcon = type => TYPE_TAG_ICONS[type] || FormOutlined;

const FieldRow = ({ field, index, total, onEdit, onDelete, onMove, prevLocked, nextLocked, conditionContext, dragHandleProps, isMobile, className, ...rest }) => {
  const { formatMessage, locale } = useIntl();
  const languages = useLocaleTextLanguages();
  const definition = getFieldDefinition(field.type);
  const conditional = hasVisibleWhen(field);
  const conditionInvalid = conditional && conditionContext && hasInvalidCondition(field, conditionContext.triggerNames);
  const TypeIcon = getFieldTypeIcon(field.type);

  return (
    <div {...rest} className={`${style['field-row']} ${className || ''}`.trim()}>
      <span className={`${style['field-row-index']} ${dragHandleProps ? style['has-handle'] : ''}`.trim()}>
        <span className={style['field-row-index-num']}>{index + 1}</span>
        {dragHandleProps ? (
          <span className={style['drag-handle']} title={formatMessage({ id: 'dragSort' })} {...dragHandleProps}>
            <HolderOutlined />
          </span>
        ) : null}
      </span>
      <div
        className={style['field-row-main']}
        {...(isMobile && !field.locked
          ? {
              role: 'button',
              tabIndex: 0,
              onClick: () => onEdit(field),
              onKeyDown: e => {
                if (e.key === 'Enter') {
                  onEdit(field);
                }
              }
            }
          : null)}
      >
        <Text className={style['field-row-label']}>{resolveLocaleText(field.label, locale, languages) || formatMessage({ id: 'untitledField' })}</Text>
        <Space size={6} wrap>
          <Tag bordered={false} color={TYPE_TAG_COLORS[field.type] || 'default'} icon={<TypeIcon />}>
            {resolveFieldTypeLabel(definition || field.type, formatMessage)}
          </Tag>
          {field.locked ? (
            <Tag bordered={false} icon={<LockOutlined />} title={formatMessage({ id: 'fieldLockedTips' })}>
              {formatMessage({ id: 'fieldLockedTag' })}
            </Tag>
          ) : null}
          {field.hidden ? (
            <Tag bordered={false} icon={<EyeInvisibleOutlined />}>
              {formatMessage({ id: 'fieldHiddenTag' })}
            </Tag>
          ) : null}
          {conditional ? (
            <Tooltip
              title={formatVisibleWhen(field.visibleWhen, {
                formatMessage,
                fieldLookup: conditionContext?.fieldLookup,
                resolveText: value => resolveLocaleText(value, locale, languages)
              })}
            >
              <Tag bordered={false} color="magenta" icon={<BranchesOutlined />}>
                {formatMessage({ id: 'fieldConditionTag' })}
              </Tag>
            </Tooltip>
          ) : null}
          {conditionInvalid ? (
            <Tooltip title={formatMessage({ id: 'fieldConditionInvalidTips' })}>
              <Tag bordered={false} color="error" icon={<WarningOutlined />}>
                {formatMessage({ id: 'fieldConditionInvalidTag' })}
              </Tag>
            </Tooltip>
          ) : null}
          {field.block ? (
            <Tag bordered={false} color="processing" icon={<ColumnWidthOutlined />}>
              {formatMessage({ id: 'fieldBlockTag' })}
            </Tag>
          ) : null}
        </Space>
      </div>
      {field.locked ? null : (
        <RowActions
          isMobile={isMobile}
          moreTitle={formatMessage({ id: 'moreActions' })}
          actions={orderActions(isMobile, [
            { key: 'up', label: formatMessage({ id: 'moveUp' }), icon: <ArrowUpOutlined />, disabled: index === 0 || prevLocked, onClick: () => onMove(field.id, 'up') },
            { key: 'down', label: formatMessage({ id: 'moveDown' }), icon: <ArrowDownOutlined />, disabled: index === total - 1 || nextLocked, onClick: () => onMove(field.id, 'down') },
            { key: 'edit', label: formatMessage({ id: 'editField' }), icon: <EditOutlined />, onClick: () => onEdit(field) },
            { key: 'delete', label: formatMessage({ id: 'deleteField' }), icon: <DeleteOutlined />, danger: true, onClick: () => onDelete(field.id) }
          ])}
        />
      )}
    </div>
  );
};

export default FieldRow;
